#include "TD_Dither.h"

#include <math.h>

#include "internal/td_bluenoise16.h"  // BLUENOISE16[256]: generated by tools/gen_bluenoise.py

// matrix dither methods share one code path: a rank table (each cell's
// lighting order, row-major, power-of-two period) plus a per-method
// scale/bias mapping ranks onto a common 0..255 threshold range:
//
//   lit  iff  shade * 256 > rank * scale + bias      (bias = scale/2)
//
// the half-step bias makes the endpoints exact (max threshold 254 < 256, min
// threshold 2 > 0... blue noise stores final thresholds directly, max 255,
// min 0 — both still exact under the strict >), and every method is monotone
// in shade. Bayer 8x8 is bit-identical to
//   shade * 64 > BAYER8[y][x] + 0.5
// because shade*256 = 4*(shade*64) exactly (power-of-two scaling commutes
// with float rounding) and 4*(r + 0.5) = 4r + 2. the host harness pins this.

// classic 8x8 Bayer, 65 effective grey levels (the default)
static const uint8_t BAYER8[64] = {
    0,  32, 8,  40, 2,  34, 10, 42,
    48, 16, 56, 24, 50, 18, 58, 26,
    12, 44, 4,  36, 14, 46, 6,  38,
    60, 28, 52, 20, 62, 30, 54, 22,
    3,  35, 11, 43, 1,  33, 9,  41,
    51, 19, 59, 27, 49, 17, 57, 25,
    15, 47, 7,  39, 13, 45, 5,  37,
    63, 31, 55, 23, 61, 29, 53, 21,
};

// 4x4 Bayer (recursive expansion of [[0,2],[3,1]]), 17 levels
static const uint8_t BAYER4[16] = {
    0,  8,  2,  10,
    12, 4,  14, 6,
    3,  11, 1,  9,
    15, 7,  13, 5,
};

// 2x2 Bayer, 5 levels
static const uint8_t BAYER2[4] = {
    0, 2,
    3, 1,
};

// 8x8 clustered-dot halftone: dots grow around two centers offset 45 deg
// (newspaper screen). clustered pixels read brighter on the OLED's gapped
// panel than the same count scattered.
static const uint8_t CLUSTER8[64] = {
    24, 10, 12, 26, 35, 47, 49, 37,
    8,  0,  2,  14, 45, 59, 61, 51,
    22, 6,  4,  16, 43, 57, 63, 53,
    30, 20, 18, 28, 33, 41, 55, 39,
    34, 46, 48, 36, 25, 11, 13, 27,
    44, 58, 60, 50, 9,  1,  3,  15,
    42, 56, 62, 52, 23, 7,  5,  17,
    32, 40, 54, 38, 31, 21, 19, 29,
};

// horizontal stripes, 5 levels: rows light in 0,2,1,3 order so the duty
// cycle tracks shade (50% = every other row)
static const uint8_t SCANLINE[4] = {0, 2, 1, 3};

// no dithering: a 1x1 "matrix" whose half-step bias is the whole threshold —
// every pixel lights iff shade > 0.5 (2 levels, pure silhouette-vs-lit look)
static const uint8_t MONO[1] = {0};

// indexed by TD_Dither; TD_DITHER_IGN is procedural and branches instead.
// the two error-diffusion methods get MONO's spec: td_ditherOn for them is
// the bare 0.5 quantizer (their diffusion lives in td_diffuseFrame, and the
// SOLID-mode shade-2.0 fill saturates through this path like every method).
const TD_DitherSpec TD_DITHER_SPECS[TD_DITHER_COUNT] = {
    {BAYER8, 7, 7, 3, 4, 2},        // TD_DITHER_BAYER8
    {BAYER4, 3, 3, 2, 16, 8},       // TD_DITHER_BAYER4
    {BAYER2, 1, 1, 1, 64, 32},      // TD_DITHER_BAYER2
    {BLUENOISE16, 15, 15, 4, 1, 0}, // TD_DITHER_BLUE16 (thresholds 0..255)
    {CLUSTER8, 7, 7, 3, 4, 2},      // TD_DITHER_CLUSTER8
    {BAYER8, 7, 7, 3, 4, 2},        // TD_DITHER_IGN (placeholder, never read)
    {SCANLINE, 0, 3, 0, 64, 32},    // TD_DITHER_SCANLINE
    {MONO, 0, 0, 0, 0, 128},        // TD_DITHER_MONO (threshold = bias = 128: shade > 0.5)
    {MONO, 0, 0, 0, 0, 128},        // TD_DITHER_FLOYD (bare quantizer; see td_diffuseFrame)
    {MONO, 0, 0, 0, 0, 128},        // TD_DITHER_ATKINSON (bare quantizer; see td_diffuseFrame)
};

static const char *const DITHER_NAMES[TD_DITHER_COUNT] = {
    "BAYER8", "BAYER4", "BAYER2", "BLUE16", "CLUST8", "IGN", "SCAN", "MONO",
    "FLOYD",  "ATKINS",
};

const char *td_ditherName(TD_Dither method) {
  return method < TD_DITHER_COUNT ? DITHER_NAMES[method] : "?";
}

// shade >= 1.0 saturates to all-on, so solid fill is just shade=2
uint8_t td_ditherOn(int x, int y, float shade, TD_Dither method) {
  if (method >= TD_DITHER_COUNT) method = TD_DITHER_BAYER8;
  if (method == TD_DITHER_IGN) {
    // interleaved gradient noise (Jimenez): t in [0,1), so shade>=1
    // always passes; the explicit clamps make both endpoints exact
    if (shade >= 1.0f) return 1;
    if (shade <= 0.0f) return 0;
    float a = 0.06711056f * (float)x + 0.00583715f * (float)y;
    float t = 52.9829189f * (a - floorf(a));
    return shade > t - floorf(t);
  }
  const TD_DitherSpec &d = TD_DITHER_SPECS[method];
  int t = d.rank[((y & d.yMask) << d.yShift) | (x & d.xMask)] * d.scale + d.bias;
  return shade * 256.0f > (float)t;
}
